#define MAXE (MAXN * MAXM * 2 + MAXN + MAXM + 10)
#define INF 1000000000

typedef struct {
    int to, rev, cap, cost;
} Edge;

Edge edges[MAXE];
int head[MAXV], next_edge[MAXE], edge_cnt;
int N, M, K;
int A[MAXN][MAXM];
int dist[MAXV], prevv[MAXV], preve[MAXV], inq[MAXV];
int V, source, sink;

void add_edge(int from, int to, int cap, int cost) {
    edges[edge_cnt] = (Edge){to, edge_cnt + 1, cap, cost};
    next_edge[edge_cnt] = head[from];
    head[from] = edge_cnt++;
    edges[edge_cnt] = (Edge){from, edge_cnt - 1, 0, -cost};
    next_edge[edge_cnt] = head[to];
    head[to] = edge_cnt++;
}

int min_cost_flow(int f) {
    int res = 0;
    int potential[MAXV];
    memset(potential, 0, sizeof(potential));
    while (f > 0) {
        for (int i = 0; i < V; i++) dist[i] = INF;
        dist[source] = 0;
        memset(inq, 0, sizeof(inq));
        int queue[MAXV * MAXV];
        int qh = 0, qt = 0;
        queue[qt++] = source;
        inq[source] = 1;
        while (qh < qt) {
            int v = queue[qh++];
            inq[v] = 0;
            for (int e = head[v]; e != -1; e = next_edge[e]) {
                if (edges[e].cap > 0) {
                    int nd = dist[v] + edges[e].cost + potential[v] - potential[edges[e].to];
                    if (dist[edges[e].to] > nd) {
                        dist[edges[e].to] = nd;
                        prevv[edges[e].to] = v;
                        preve[edges[e].to] = e;
                        if (!inq[edges[e].to]) {
                            queue[qt++] = edges[e].to;
                            inq[edges[e].to] = 1;
                        }
                    }
                }
            }
        }
        if (dist[sink] == INF) return -1;
        for (int v = 0; v < V; v++) potential[v] += dist[v];
        int d = f;
        for (int v = sink; v != source; v = prevv[v]) {
            d = d < edges[preve[v]].cap ? d : edges[preve[v]].cap;
        }
        f -= d;
        res += d * potential[sink];
        for (int v = sink; v != source; v = prevv[v]) {
            edges[preve[v]].cap -= d;
            edges[edges[preve[v]].rev].cap += d;
        }
    }
    return res;
}

