            add_edge(i, N + j, 1, -A[i][j]);

    int max_flow = N * K < M * K ? N * K : M * K;
    int min_cost = min_cost_flow(max_flow);
    int max_sum = -min_cost;

    // Reconstruct selection
    int selected[MAXN][MAXM];
