typedef long long ll;

typedef struct {
    int to, rev, cap;
    ll cost;
} Edge;

typedef struct {
    Edge *data;
    int sz, cap;
} Vec;

static void vec_push(Vec *v, Edge e) {
    if (v->sz == v->cap) {
        v->cap = v->cap ? v->cap * 2 : 4;
        v->data = (Edge*)realloc(v->data, sizeof(Edge) * v->cap);
    }
    v->data[v->sz++] = e;
}

typedef struct {
    int n;
    Vec *g;
} MCMF;

static void add_edge(MCMF *mf, int s, int t, int cap, ll cost) {
    Edge a = {t, mf->g[t].sz, cap, cost};
    Edge b = {s, mf->g[s].sz, 0, -cost};
    vec_push(&mf->g[s], a);
    vec_push(&mf->g[t], b);
}

static ll minll(ll a, ll b) { return a < b ? a : b; }

int main(void) {
    int N, M, K;
    if (scanf("%d %d %d", &N, &M, &K) != 3) return 0;

    ll **A = (ll**)malloc(sizeof(ll*) * N);
    for (int i = 0; i < N; i++) {
        A[i] = (ll*)malloc(sizeof(ll) * M);
        for (int j = 0; j < M; j++) scanf("%lld", &A[i][j]);
    }

    /*
      Reduce to min-cost max-flow with optional selections.
      Nodes:
        S, rows, cols, T
      Edges:
        S -> row_i cap K cost 0
        row_i -> col_j cap 1 cost -A[i][j]
        col_j -> T cap K cost 0

      To allow choosing fewer than possible edges, add:
        S -> T cap INF cost 0
      Then send exactly N*K + M*K? No.
      Better:
        We want any amount of flow up to row/col caps maximizing profit.
        Standard trick:
          Add super source SS -> S with cap INF cost 0
          T -> TT, and S -> TT direct? cumbersome.

      Easier equivalent:
        Add dummy column/row? Not enough.

      Better formulation:
        Min-cost circulation via edge T->S with negative large? unnecessary.

      Since all profits are nonnegative, any feasible chosen square increases objective by A>=0.
      So optimal solution chooses as many positive/zero-profit squares as beneficial.
      Since zero also harmless, maximizing sum is same as min-cost max-flow where we keep augmenting
      while shortest path cost < 0. Start from S to T network.
    */

    int V = 2 + N + M;
    int S = 0;
    int T = V - 1;
    MCMF mf;
    mf.n = V;
    mf.g = (Vec*)calloc(V, sizeof(Vec));

    for (int i = 0; i < N; i++) add_edge(&mf, S, 1 + i, K, 0);
    for (int j = 0; j < M; j++) add_edge(&mf, 1 + N + j, T, K, 0);

    int **edge_idx = (int**)malloc(sizeof(int*) * N);
    for (int i = 0; i < N; i++) {
        edge_idx[i] = (int*)malloc(sizeof(int) * M);
        for (int j = 0; j < M; j++) {
            edge_idx[i][j] = mf.g[1 + i].sz;
            add_edge(&mf, 1 + i, 1 + N + j, 1, -A[i][j]);
        }
    }

    ll *dist = (ll*)malloc(sizeof(ll) * V);
    int *inq = (int*)malloc(sizeof(int) * V);
    int *pv = (int*)malloc(sizeof(int) * V);
    int *pe = (int*)malloc(sizeof(int) * V);
    int *q = (int*)malloc(sizeof(int) * (V * 10 + 5));

    ll totalCost = 0;
    while (1) {
        const ll INF = (1LL << 60);
        for (int i = 0; i < V; i++) {
            dist[i] = INF;
            inq[i] = 0;
            pv[i] = -1;
            pe[i] = -1;
        }

        int head = 0, tail = 0;
        dist[S] = 0;
        q[tail++] = S;
        inq[S] = 1;

        while (head != tail) {
            int v = q[head++];
            if (head == V * 10 + 5) head = 0;
            inq[v] = 0;

            for (int ei = 0; ei < mf.g[v].sz; ei++) {
                Edge *e = &mf.g[v].data[ei];
                if (e->cap <= 0) continue;
                if (dist[e->to] > dist[v] + e->cost) {
                    dist[e->to] = dist[v] + e->cost;
                    pv[e->to] = v;
                    pe[e->to] = ei;
                    if (!inq[e->to]) {
                        q[tail++] = e->to;
                        if (tail == V * 10 + 5) tail = 0;
                        inq[e->to] = 1;
                    }
                }
            }
        }

        if (dist[T] >= 0 || dist[T] == (1LL << 60)) break;

        int addf = 1e9;
        for (int v = T; v != S; v = pv[v]) {
            Edge *e = &mf.g[pv[v]].data[pe[v]];
            if (e->cap < addf) addf = e->cap;
        }

        for (int v = T; v != S; v = pv[v]) {
            Edge *e = &mf.g[pv[v]].data[pe[v]];
            Edge *r = &mf.g[e->to].data[e->rev];
            e->cap -= addf;
            r->cap += addf;
        }

        totalCost += dist[T] * addf;
    }

    ll answer = -totalCost;
    printf("%lld\n", answer);

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            Edge *e = &mf.g[1 + i].data[edge_idx[i][j]];
            int used = (e->cap == 0); /* original cap was 1 */
            putchar(used ? '1' : '0');
            if (j + 1 < M) putchar(' ');
        }
        putchar('\n');
    }

    return 0;
}

