using ll = long long;
const ll INF = 1e18;

struct Edge {
    int to, rev;
    ll cap, cost;
};

class MinCostFlow {
public:
    int n;
    vector<vector<Edge>> g;
    vector<ll> pot, dist;
    vector<int> prevv, preve;

    MinCostFlow(int n_) : n(n_), g(n_), pot(n_, 0), dist(n_), prevv(n_), preve(n_) {}

    void add_edge(int from, int to, ll cap, ll cost) {
        g[from].push_back({to, (int)g[to].size(), cap, cost});
        g[to].push_back({from, (int)g[from].size()-1, 0, -cost});
    }

    pair<ll, ll> flow(int s, int t, ll maxf) {
        ll flow = 0, cost = 0;
        while (flow < maxf) {
            fill(dist.begin(), dist.end(), INF);
            dist[s] = 0;
            priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
            pq.push({0, s});
            while (!pq.empty()) {
                auto [d, v] = pq.top(); pq.pop();
                if (dist[v] < d) continue;
                for (int i = 0; i < (int)g[v].size(); i++) {
                    auto &e = g[v][i];
                    if (e.cap > 0 && dist[e.to] > dist[v] + e.cost + pot[v] - pot[e.to]) {
                        dist[e.to] = dist[v] + e.cost + pot[v] - pot[e.to];
                        prevv[e.to] = v;
                        preve[e.to] = i;
                        pq.push({dist[e.to], e.to});
                    }
                }
            }
            if (dist[t] == INF) break;
            for (int v = 0; v < n; v++) pot[v] += dist[v];

            ll d = maxf - flow;
            for (int v = t; v != s; v = prevv[v]) {
                d = min(d, g[prevv[v]][preve[v]].cap);
            }
            flow += d;
            cost += d * pot[t];
            for (int v = t; v != s; v = prevv[v]) {
                auto &e = g[prevv[v]][preve[v]];
                e.cap -= d;
                g[v][e.rev].cap += d;
            }
        }
        return {flow, cost};
    }
};

