#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Edge {
    int to, rev;
    int cap;
    ll cost;
};

struct MinCostFlow {
    int N;
    vector<vector<Edge>> g;
    MinCostFlow(int n) : N(n), g(n) {}

    void addEdge(int s, int t, int cap, ll cost) {
        Edge a{t, (int)g[t].size(), cap, cost};
        Edge b{s, (int)g[s].size(), 0, -cost};
        g[s].push_back(a);
        g[t].push_back(b);
    }

    pair<int, ll> minCostMaxFlow(int s, int t, int maxf) {
        const ll INF = (1LL << 60);
        int flow = 0;
        ll cost = 0;
        vector<ll> pot(N, 0), dist(N);
        vector<int> pv(N), pe(N);

        while (flow < maxf) {
            fill(dist.begin(), dist.end(), INF);
            dist[s] = 0;
            priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;
            pq.push({0, s});

            while (!pq.empty()) {
                auto [d, v] = pq.top();
                pq.pop();
                if (d != dist[v]) continue;
                for (int i = 0; i < (int)g[v].size(); i++) {
                    const Edge &e = g[v][i];
                    if (e.cap <= 0) continue;
                    ll nd = d + e.cost + pot[v] - pot[e.to];
                    if (dist[e.to] > nd) {
                        dist[e.to] = nd;
                        pv[e.to] = v;
                        pe[e.to] = i;
                        pq.push({nd, e.to});
                    }
                }
            }

            if (dist[t] == INF) break;

            for (int i = 0; i < N; i++) {
                if (dist[i] < INF) pot[i] += dist[i];
            }

            int addf = maxf - flow;
            int v = t;
            while (v != s) {
                addf = min(addf, g[pv[v]][pe[v]].cap);
                v = pv[v];
            }

            v = t;
            while (v != s) {
                Edge &e = g[pv[v]][pe[v]];
                e.cap -= addf;
                g[v][e.rev].cap += addf;
                v = pv[v];
            }

            flow += addf;
            cost += 1LL * addf * pot[t];
        }
        return {flow, cost};
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, K;
    cin >> N >> M >> K;
    vector<vector<ll>> A(N, vector<ll>(M));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) cin >> A[i][j];
    }

    // Standard construction:
    // source -> rows (cap K, cost 0)
    // rows -> cols (cap 1, cost -A[i][j])
    // cols -> sink (cap K, cost 0)
    //
    // To allow choosing fewer than K per row/col, add source->sink with large cap and cost 0,
    // and send exactly N*K flow where rows/cols each can absorb at most K.
    // Here we use square output format N x M with 'X' for chosen, '.' otherwise.

    int S = N + M;
    int T = N + M + 1;
    int V = N + M + 2;

    MinCostFlow mcf(V);

    for (int i = 0; i < N; i++) {
        mcf.addEdge(S, i, K, 0);
    }
    for (int j = 0; j < M; j++) {
        mcf.addEdge(N + j, T, K, 0);
    }

    vector<vector<int>> edgeIndex(N, vector<int>(M));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            edgeIndex[i][j] = (int)mcf.g[i].size();
            mcf.addEdge(i, N + j, 1, -A[i][j]);
        }
    }

    // Optional unused flow
    mcf.addEdge(S, T, N * K, 0);

    auto [flow, cost] = mcf.minCostMaxFlow(S, T, N * K);

    ll ans = -cost;
    cout << ans << '\n';

    vector<string> res(N, string(M, '.'));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            const Edge &e = mcf.g[i][edgeIndex[i][j]];
            // original cap was 1, so if now 0 then used
            if (e.cap == 0) res[i][j] = 'X';
        }
    }

    for (int i = 0; i < N; i++) {
        cout << res[i] << '\n';
    }

    return 0;
}

import java.util.*;

public class Main {
    static class Edge {
        int to, rev, cap;
        long cost;
        Edge(int to, int rev, int cap, long cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }
    }

    static List<Edge>[] graph;
    static long[] potential, dist;
    static int[] prevv, preve;

    static void addEdge(int from, int to, int cap, long cost) {
        graph[from].add(new Edge(to, graph[to].size(), cap, cost));
        graph[to].add(new Edge(from, graph[from].size() - 1, 0, -cost));
    }

    static long minCostFlow(int s, int t, int maxf) {
        int n = graph.length;
        potential = new long[n];
        dist = new long[n];
        prevv = new int[n];
        preve = new int[n];
        long res = 0;
        int flow = 0;

        while (flow < maxf) {
            Arrays.fill(dist, Long.MAX_VALUE);
            dist[s] = 0;
            boolean updated;
            // Bellman-Ford to handle negative costs initially
            for (int i = 0; i < n; i++) {
                updated = false;
                for (int v = 0; v < n; v++) {
                    if (dist[v] == Long.MAX_VALUE) continue;
                    for (int j = 0; j < graph[v].size(); j++) {
                        Edge e = graph[v].get(j);
                        if (e.cap > 0 && dist[e.to] > dist[v] + e.cost + potential[v] - potential[e.to]) {
                            dist[e.to] = dist[v] + e.cost + potential[v] - potential[e.to];
                            prevv[e.to] = v;
                            preve[e.to] = j;
                            updated = true;
                        }
                    }
                }
                if (!updated) break;
            }

            if (dist[t] == Long.MAX_VALUE) break;

            for (int v = 0; v < n; v++) {
                if (dist[v] < Long.MAX_VALUE)
                    potential[v] += dist[v];
            }

            int d = maxf - flow;
            for (int v = t; v != s; v = prevv[v]) {
                d = Math.min(d, graph[prevv[v]].get(preve[v]).cap);
            }
            flow += d;
            res += d * potential[t];
            for (int v = t; v != s; v = prevv[v]) {
                Edge e = graph[prevv[v]].get(preve[v]);
                e.cap -= d;
                graph[v].get(e.rev).cap += d;
            }
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        int K = sc.nextInt();
        long[][] A = new long[N][M];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                A[i][j] = sc.nextLong();
            }
        }

        int nodeCount = 2 + N + M;
        int S = N + M;
        int T = N + M + 1;
        graph = new ArrayList[nodeCount];
        for (int i = 0; i < nodeCount; i++) graph[i] = new ArrayList<>();

        for (int i = 0; i < N; i++) {
            addEdge(S, i, K, 0);
        }
        for (int j = 0; j < M; j++) {
            addEdge(N + j, T, K, 0);
        }
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                addEdge(i, N + j, 1, -A[i][j]); // negative for min-cost → max sum
            }
        }

        long maxSum = -minCostFlow(S, T, Integer.MAX_VALUE);

        // Reconstruct chosen squares
        boolean[][] chosen = new boolean[N][M];
        for (int i = 0; i < N; i++) {
            for (Edge e : graph[i]) {
                if (e.to >= N && e.to < N + M && e.cap == 0) {
                    int j = e.to - N;
                    chosen[i][j] = true;
                }
            }
        }

        System.out.println(maxSum);
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                System.out.print(chosen[i][j] ? "1" : "0");
            }
            System.out.println();
        }
    }
}

import java.util.*;

public class Main {
    // MCMF implementation
    static int[] head, nxt, to, cap;
    static long[] cost;
    static int cnt;
    static int V;

    static void init(int v, int e) {
        V = v;
        head = new int[v]; Arrays.fill(head, -1);
        nxt = new int[e*2]; to = new int[e*2]; cap = new int[e*2]; cost = new long[e*2];
        cnt = 0;
    }

    static void addEdge(int u, int v, int c, long w) {
        to[cnt]=v; cap[cnt]=c; cost[cnt]=w; nxt[cnt]=head[u]; head[u]=cnt++;
        to[cnt]=u; cap[cnt]=0; cost[cnt]=-w; nxt[cnt]=head[v]; head[v]=cnt++;
    }

    // Returns {flow, cost} of one augmenting path with min cost; returns null if no path or positive cost
    static long[] spfa(int s, int t) {
        long[] dist = new long[V]; Arrays.fill(dist, Long.MAX_VALUE/2);
        int[] prevv = new int[V], preve = new int[V];
        boolean[] inq = new boolean[V];
        dist[s] = 0;
        Queue<Integer> q = new ArrayDeque<>();
        q.add(s); inq[s] = true;
        while (!q.isEmpty()) {
            int u = q.poll(); inq[u] = false;
            for (int e = head[u]; e != -1; e = nxt[e]) {
                if (cap[e] > 0 && dist[u] + cost[e] < dist[to[e]]) {
                    dist[to[e]] = dist[u] + cost[e];
                    prevv[to[e]] = u; preve[to[e]] = e;
                    if (!inq[to[e]]) { q.add(to[e]); inq[to[e]] = true; }
                }
            }
        }
        if (dist[t] >= 0) return null;
        // augment
        int f = Integer.MAX_VALUE;
        for (int v = t; v != s; v = prevv[v]) f = Math.min(f, cap[preve[v]]);
        for (int v = t; v != s; v = prevv[v]) { cap[preve[v]] -= f; cap[preve[v]^1] += f; }
        return new long[]{f, dist[t] * f};
    }
    // ... rest of solution
}

import java.io.*;
import java.util.*;

/*
Min-cost max-flow formulation.

We need choose cells in an N x M grid, each row/column used at most K times,
maximizing sum of chosen A[i][j] >= 0.

Classic reduction:
source -> each row (capacity K, cost 0)
row i -> col j (capacity 1, cost -A[i][j])
each col -> sink (capacity K, cost 0)

Because all A >= 0 and capacities are "at most K", sending any negative-cost path is beneficial.
To allow choosing fewer than K in a row/column, add direct edge row i -> sink with capacity K, cost 0.
Then send exactly N*K units from source. Any unit either picks some column via a cell, or goes directly to sink meaning "unused".
This guarantees feasibility and maximization.

Need also output one optimal selection. Chosen cells are row->col edges with flow 1.

Complexity: O(F * V^2) with potentials/SPFA/Dijkstra. Here F = N*K.
Using potentials + Dijkstra on reduced costs works since initial negative edges exist,
so initialize potentials by SPFA once.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Edge {
        int to, rev, cap;
        long cost;
        Edge(int to, int rev, int cap, long cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }
    }

    static class MinCostFlow {
        int n;
        ArrayList<Edge>[] g;

        @SuppressWarnings("unchecked")
        MinCostFlow(int n) {
            this.n = n;
            g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        }

        Edge addEdge(int s, int t, int cap, long cost) {
            Edge a = new Edge(t, g[t].size(), cap, cost);
            Edge b = new Edge(s, g[s].size(), 0, -cost);
            g[s].add(a);
            g[t].add(b);
            return a;
        }

        long[] minCostFlow(int s, int t, int maxf) {
            long[] h = new long[n]; // potentials
            long INF = Long.MAX_VALUE / 4;

            // Initial potentials by SPFA because negative edges exist.
            Arrays.fill(h, INF);
            h[s] = 0;
            boolean[] inq = new boolean[n];
            int[] q = new int[n * 4 + 5];
            int head = 0, tail = 0;
            q[tail++] = s;
            inq[s] = true;
            while (head != tail) {
                int v = q[head++];
                if (head == q.length) head = 0;
                inq[v] = false;
                for (Edge e : g[v]) {
                    if (e.cap > 0 && h[e.to] > h[v] + e.cost) {
                        h[e.to] = h[v] + e.cost;
                        if (!inq[e.to]) {
                            q[tail++] = e.to;
                            if (tail == q.length) tail = 0;
                            inq[e.to] = true;
                        }
                    }
                }
            }
            for (int i = 0; i < n; i++) if (h[i] == INF) h[i] = 0;

            long res = 0;
            int flow = 0;

            long[] dist = new long[n];
            int[] pv = new int[n];
            int[] pe = new int[n];

            while (flow < maxf) {
                Arrays.fill(dist, INF);
                dist[s] = 0;

                PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
                pq.add(new long[]{0, s});

                while (!pq.isEmpty()) {
                    long[] cur = pq.poll();
                    long d = cur[0];
                    int v = (int) cur[1];
                    if (d != dist[v]) continue;
                    for (int i = 0; i < g[v].size(); i++) {
                        Edge e = g[v].get(i);
                        if (e.cap <= 0) continue;
                        long nd = d + e.cost + h[v] - h[e.to];
                        if (dist[e.to] > nd) {
                            dist[e.to] = nd;
                            pv[e.to] = v;
                            pe[e.to] = i;
                            pq.add(new long[]{nd, e.to});
                        }
                    }
                }

                if (dist[t] == INF) break;

                for (int i = 0; i < n; i++) {
                    if (dist[i] < INF) h[i] += dist[i];
                }

                int addf = maxf - flow;
                for (int v = t; v != s; v = pv[v]) {
                    Edge e = g[pv[v]].get(pe[v]);
                    addf = Math.min(addf, e.cap);
                }

                flow += addf;
                res += (long) addf * h[t];

                for (int v = t; v != s; v = pv[v]) {
                    Edge e = g[pv[v]].get(pe[v]);
                    e.cap -= addf;
                    g[v].get(e.rev).cap += addf;
                }
            }

            return new long[]{flow, res};
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int M = fs.nextInt();
        int K = fs.nextInt();

        long[][] A = new long[N][M];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                A[i][j] = fs.nextInt();
            }
        }

        int S = 0;
        int rowStart = 1;
        int colStart = rowStart + N;
        int T = colStart + M;
        int V = T + 1;

        MinCostFlow mcf = new MinCostFlow(V);

        for (int i = 0; i < N; i++) {
            mcf.addEdge(S, rowStart + i, K, 0);
        }

        Edge[][] cellEdge = new Edge[N][M];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                cellEdge[i][j] = mcf.addEdge(rowStart + i, colStart + j, 1, -A[i][j]);
            }
            mcf.addEdge(rowStart + i, T, K, 0); // unused capacity for row i
        }

        for (int j = 0; j < M; j++) {
            mcf.addEdge(colStart + j, T, K, 0);
        }

        long[] ans = mcf.minCostFlow(S, T, N * K);
        long maxSum = -ans[1];

        StringBuilder out = new StringBuilder();
        out.append(maxSum).append('\n');

        // Output one optimal choice as N lines of length M using 'X' for chosen, '.' otherwise.
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                // original forward edge had cap 1; if now cap 0, then flow 1 was sent
                out.append(cellEdge[i][j].cap == 0 ? 'X' : '.');
            }
            out.append('\n');
        }

        System.out.print(out.toString());
    }
}
